//! Runs the real ffprobe against a file generated by ffmpeg (both must be on PATH).

use std::process::Command;

use flixnet_media::{Ffprobe, StreamKind};

#[tokio::test]
async fn probes_a_generated_file() {
    let dir = tempfile::tempdir().unwrap();
    let file = dir.path().join("sample.mkv");
    let status = Command::new("ffmpeg")
        .args(["-hide_banner", "-loglevel", "error", "-y"])
        .args(["-f", "lavfi", "-i", "testsrc=s=320x240:r=25:d=2"])
        .args(["-f", "lavfi", "-i", "sine=f=440:d=2"])
        .args([
            "-c:v",
            "mpeg4",
            "-c:a",
            "mp2",
            "-metadata:s:a:0",
            "language=deu",
        ])
        .arg(&file)
        .status()
        .expect("ffmpeg must be installed for media tests");
    assert!(status.success());

    let info = Ffprobe::new("ffprobe").probe(&file).await.unwrap();
    assert_eq!(info.container.as_deref(), Some("mkv"));
    let duration = info.duration_ms.unwrap();
    assert!((1900..=2100).contains(&duration), "duration {duration}");
    let video = info
        .streams
        .iter()
        .find(|s| s.kind == StreamKind::Video)
        .unwrap();
    assert_eq!((video.width, video.height), (Some(320), Some(240)));
    assert_eq!(video.hdr, Some("sdr"));
    let audio = info
        .streams
        .iter()
        .find(|s| s.kind == StreamKind::Audio)
        .unwrap();
    assert_eq!(audio.language.as_deref(), Some("deu"));
}

#[tokio::test]
async fn reports_unreadable_files() {
    let dir = tempfile::tempdir().unwrap();
    let file = dir.path().join("broken.mkv");
    std::fs::write(&file, b"definitely not a video").unwrap();
    let err = Ffprobe::new("ffprobe").probe(&file).await.unwrap_err();
    assert!(matches!(err, flixnet_media::ProbeError::Failed(_)), "{err}");
}

#[tokio::test]
async fn missing_binary_is_a_clear_error() {
    let err = Ffprobe::new("ffprobe-does-not-exist")
        .probe(std::path::Path::new("x.mkv"))
        .await
        .unwrap_err();
    assert!(
        matches!(err, flixnet_media::ProbeError::Spawn { .. }),
        "{err}"
    );
}
